export default function TasmiRecordPage() {
    const { t, i18n } = useTranslation('tasmiRecord');
    const lang = i18n.resolvedLanguage;
    const [params] = useSearchParams();
    const c = params.get('c') || '';
    const saved = readLs(c) || {};

    const [script, setScript] = useState(null);
    const [loadErr, setLoadErr] = useState(null);
    const [pid, setPid] = useState(saved.participantId || null);
    const [stage, setStage] = useState(saved.participantId ? 'mic' : 'consent');
    const [status, setStatus] = useState(saved.status || {}); // itemId → 'saved' | 'pending'
    const [takes, setTakes] = useState(saved.takes || {});   // itemId → last take number
    const [idx, setIdx] = useState(0);
    const [profile, setProfile] = useState({ gender: '', ageBand: '', level: '' });
    const [busy, setBusy] = useState(false);
    const [err, setErr] = useState(null);

    const [level, setLevel] = useState(0);
    const [rec, setRec] = useState(null);       // { url, blob, type, durationMs }
    const [recording, setRecording] = useState(false);
    const [progress, setProgress] = useState(null);
    const [online, setOnline] = useState(typeof navigator === 'undefined' ? true : navigator.onLine);

    const stream = useRef(null);
    const recorder = useRef(null);
    const meterRaf = useRef(0);
    const audioCtx = useRef(null);
    const stopTimer = useRef(0);
    const retryTimer = useRef(0);
    const backoff = useRef(2000);
    const draining = useRef(false);
    const inflight = useRef(new Set()); // job ids Save is sending right now
    const mime = useRef(pickMime());

    // fonts
    useEffect(() => {
        window.scrollTo(0, 0);
        for (const href of [FONTS, SCRIPT_FONTS[lang]].filter(Boolean)) {
            if (!document.querySelector(`link[href="${href}"]`)) {
                const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = href; document.head.appendChild(l);
            }
        }
    }, [lang]);

    // the script (token check)
    useEffect(() => {
        if (!c) { setLoadErr(t('errors.noLink')); return; }
        fetch(`${API}/script?c=${encodeURIComponent(c)}`)
            .then(async (r) => { const j = await r.json().catch(() => null); if (!r.ok) throw Object.assign(new Error(j?.error), { status: r.status }); return j.data; })
            .then((d) => {
                setScript(d.script);
                const first = d.script.findIndex((i) => !(readLs(c)?.status || {})[i.id]);
                setIdx(first < 0 ? d.script.length : first);
            })
            .catch((e) => setLoadErr(e.status === 403 ? t('errors.badLink') : t('errors.offline')));
    }, [c, t]);

    useEffect(() => { if (c) writeLs(c, { participantId: pid, status, takes }); }, [c, pid, status, takes]);

    const mark = useCallback((itemId, s) => setStatus((x) => ({ ...x, [itemId]: s })), []);

    // ── the offline queue ────────────────────────────────────────────────────
    const drain = useCallback(async () => {
        if (draining.current) return;
        draining.current = true;
        clearTimeout(retryTimer.current);
        let failed = false;
        try {
            const jobs = ((await qAll()) || []).filter((j) => j.c === c && !inflight.current.has(j.id));
            for (const job of jobs) {
                try {
                    await uploadJob(job, () => {});
                    await qDel(job.id);
                    mark(job.itemId, 'saved');
                } catch (e) {
                    if (permanent(e)) { await qDel(job.id); mark(job.itemId, undefined); } else failed = true;
                }
            }
        } finally { draining.current = false; }
        if (failed) {
            retryTimer.current = setTimeout(drain, backoff.current);
            backoff.current = Math.min(backoff.current * 2, 120000);
        } else backoff.current = 2000;
    }, [c, mark]);

    useEffect(() => {
        const on = () => { setOnline(true); backoff.current = 2000; drain(); };
        const off = () => setOnline(false);
        window.addEventListener('online', on);
        window.addEventListener('offline', off);
        if (pid) drain();
        return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off); clearTimeout(retryTimer.current); };
    }, [drain, pid]);

    // ── mic ──────────────────────────────────────────────────────────────────
    const stopMeter = () => { cancelAnimationFrame(meterRaf.current); audioCtx.current?.close?.().catch(() => {}); audioCtx.current = null; };
    useEffect(() => () => { stopMeter(); clearTimeout(stopTimer.current); stream.current?.getTracks().forEach((tr) => tr.stop()); }, []);

    const openMic = async () => {
        setErr(null);
        if (!navigator.mediaDevices?.getUserMedia || mime.current === null) { setErr(t('errors.noRecorder')); return; }
        try {
            if (!stream.current) stream.current = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: true, noiseSuppression: false, autoGainControl: true } });
            const Ctx = window.AudioContext || window.webkitAudioContext;
            const ctx = new Ctx();
            audioCtx.current = ctx;
            const an = ctx.createAnalyser();
            an.fftSize = 512;
            ctx.createMediaStreamSource(stream.current).connect(an);
            const buf = new Uint8Array(an.fftSize);
            const tick = () => {
                an.getByteTimeDomainData(buf);
                let peak = 0;
                for (const v of buf) peak = Math.max(peak, Math.abs(v - 128));
                setLevel(Math.min(1, peak / 70));
                meterRaf.current = requestAnimationFrame(tick);
            };
            tick();
        } catch { setErr(t('errors.micDenied')); }
    };

    const start = async () => {
        setBusy(true); setErr(null);
        try {
            const p = await post('/session', { c, consent: true, ...Object.fromEntries(Object.entries(profile).filter(([, v]) => v)) });
            setPid(p.participantId);
            setStage('mic');
        } catch (e) { setErr(e.status === 403 ? t('errors.badLink') : t('errors.offline')); }
        setBusy(false);
    };

    // ── recording ────────────────────────────────────────────────────────────
    const item = script && script[idx];

    const record = async () => {
        setErr(null);
        if (!stream.current) await openMic();
        if (!stream.current) return;
        const chunks = [];
        let r;
        try { r = new MediaRecorder(stream.current, { ...(mime.current ? { mimeType: mime.current } : {}), audioBitsPerSecond: BITRATE }); }
        catch { r = new MediaRecorder(stream.current); }
        const began = Date.now();
        r.ondataavailable = (e) => e.data.size && chunks.push(e.data);
        r.onstop = () => {
            const type = (r.mimeType || mime.current || 'audio/webm').split(';')[0];
            const blob = new Blob(chunks, { type });
            setRec({ blob, type, durationMs: Date.now() - began, url: URL.createObjectURL(blob) });
            setRecording(false);
        };
        recorder.current = r;
        if (rec?.url) URL.revokeObjectURL(rec.url);
        setRec(null);
        r.start();
        setRecording(true);
        stopTimer.current = setTimeout(() => r.state === 'recording' && r.stop(), MAX_MS);
    };
    const stop = () => { clearTimeout(stopTimer.current); if (recorder.current?.state === 'recording') recorder.current.stop(); };

    const next = () => {
        if (rec?.url) URL.revokeObjectURL(rec.url);
        setRec(null); setProgress(null);
        const after = script.findIndex((i, k) => k > idx && !status[i.id]);
        const any = script.findIndex((i) => !status[i.id] && i.id !== item.id);
        setIdx(after >= 0 ? after : any >= 0 ? any : script.length);
    };

    const save = async () => {
        if (!rec || !item) return;
        if (rec.durationMs < 400 || rec.blob.size < 1000) { setErr(t('errors.tooShort')); return; }
        if (rec.blob.size > 2 * 1024 * 1024) { setErr(t('errors.tooLong')); return; }
        const take = Math.min((takes[item.id] || 0) + 1, 3);
        setTakes((x) => ({ ...x, [item.id]: take }));
        const job = { id: `${c}|${pid}|${item.id}|${take}`, c, participantId: pid, itemId: item.id, take, type: rec.type, blob: rec.blob, durationMs: rec.durationMs };
        // Into the queue first: if the tab closes mid-upload, the next visit sends it.
        await qPut(job);
        mark(item.id, 'pending');
        setProgress(0);
        inflight.current.add(job.id);
        try {
            await uploadJob(job, setProgress);
            await qDel(job.id);
            mark(item.id, 'saved');
        } catch (e) {
            if (permanent(e)) { await qDel(job.id); mark(item.id, undefined); setErr(e.message); setProgress(null); return; }
        } finally { inflight.current.delete(job.id); }
        drain();
        next();
    };

    const total = script?.length || 0;
    const savedCount = Object.values(status).filter((s) => s === 'saved').length;
    const pendingCount = Object.values(status).filter((s) => s === 'pending').length;

    // ── render ───────────────────────────────────────────────────────────────
    const header = (
        <>
            <div className="eyebrow">{t('eyebrow')}</div>
            <h1>{t('title')}<span className="ar" lang="ar">مُعَلِّم</span></h1>
        </>
    );

    const ayah = (it) => {
        const words = it.text.split(' ');
        const tg = it.target.word - it.word_span[0];
        return (
            <>
                <p className="ayah" lang="ar">{words.map((w, k) => <React.Fragment key={k}>{k ? ' ' : ''}<span className={k === tg ? 'tg' : undefined}>{w}</span></React.Fragment>)}</p>
                <div className="ref">{t('ref', { surah: it.surah, ayah: it.ayah })} · <span lang="ar">{AR(it.surah)}:{AR(it.ayah)}</span></div>
            </>
        );
    };

    let body;
    if (loadErr) body = <div className="card"><p className="err">{loadErr}</p></div>;
    else if (!script) body = <div className="card"><p>{t('loading')}</p></div>;
    else if (stage === 'consent') body = (
        <div className="card">
            <h2 style={{ font: '500 28px var(--f-display)', margin: 0 }}>{t('consent.heading')}</h2>
            <p>{t('consent.intro')}</p>
            <label className="f">{t('profile.gender')}
                <select value={profile.gender} onChange={(e) => setProfile({ ...profile, gender: e.target.value })}>
                    <option value="">{t('profile.skip')}</option>
                    <option value="female">{t('profile.female')}</option>
                    <option value="male">{t('profile.male')}</option>
                </select>
            </label>
            <label className="f">{t('profile.age')}
                <select value={profile.ageBand} onChange={(e) => setProfile({ ...profile, ageBand: e.target.value })}>
                    <option value="">{t('profile.skip')}</option>
                    {['under13', '13-17', '18-29', '30-49', '50plus'].map((a) => <option key={a} value={a}>{t(`profile.ages.${a}`)}</option>)}
                </select>
            </label>
            <label className="f">{t('profile.level')}
                <select value={profile.level} onChange={(e) => setProfile({ ...profile, level: e.target.value })}>
                    <option value="">{t('profile.skip')}</option>
                    {['beginner', 'intermediate', 'advanced', 'teacher'].map((a) => <option key={a} value={a}>{t(`profile.levels.${a}`)}</option>)}
                </select>
            </label>
            {err && <p className="err">{err}</p>}
            <div className="row"><button className="btn gold wide" disabled={busy} onClick={start}>{busy ? t('wait') : t('consent.start')}</button></div>
        </div>
    );
    else if (stage === 'mic') body = (
        <div className="card">
            <h2 style={{ font: '500 28px var(--f-display)', margin: 0 }}>{t('mic.heading')}</h2>
            <p>{t('mic.body')}</p>
            <div className="meter" role="meter" aria-label={t('mic.level')} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(level * 100)}><i style={{ width: `${Math.round(level * 100)}%` }} /></div>
            <p className={level > 0.15 ? 'ok' : undefined}>{level > 0.15 ? t('mic.good') : t('mic.speak')}</p>
            {err && <p className="err">{err}</p>}
            <div className="row">
                <button className="btn ghost" onClick={openMic}>{t('mic.test')}</button>
                <button className="btn gold" onClick={() => { stopMeter(); setStage('read'); }} disabled={!stream.current}>{savedCount ? t('mic.resume', { n: savedCount }) : t('mic.continue')}</button>
            </div>
        </div>
    );
    else if (!item) body = (
        <div className="card center">
            <h2 style={{ font: '500 32px var(--f-display)', margin: 0 }}>{t('done.heading')}</h2>
            <p lang="ar" style={{ font: '400 28px/2 var(--f-quran)', color: 'var(--gold)' }}>جَزَاكُمُ ٱللَّهُ خَيْرًا</p>
            <p>{pendingCount ? t('done.pending', { n: pendingCount }) : t('done.body')}</p>
        </div>
    );
    else body = (
        <div className="card">
            <div className="dots" aria-label={t('progress', { saved: savedCount, total })}>
                {script.map((it, k) => (
                    <button key={it.id} className={`dot ${status[it.id] || ''} ${k === idx ? 'now' : ''}`} onClick={() => { if (!recording) { setRec(null); setIdx(k); } }}
                        aria-label={`${k + 1}: ${status[it.id] ? t(`state.${status[it.id]}`) : t('state.todo')}`}>{status[it.id] === 'saved' ? '✓' : k + 1}</button>
                ))}
            </div>
            <p style={{ fontSize: 14 }}>{t('progress', { saved: savedCount, total })}{!online && ` · ${t('offline')}`}</p>
            <div className="rule">{t(`rules.${item.target.rule}`)}</div>
            <p className={`ask ${item.intended === 'correct' ? '' : 'fault'}`}>{t(`ask.${item.intended}`)}</p>
            {ayah(item)}
            <button className={`rec ${recording ? 'on' : ''}`} onClick={recording ? stop : record} aria-label={recording ? t('stop') : t('record')} />
            <p className="center" style={{ marginTop: 0 }}>{recording ? t('recording') : rec ? t('review') : t('tapToRecord')}</p>
            {rec && !recording && (
                <>
                    <audio controls src={rec.url} />
                    <div className="row">
                        <button className="btn ghost" onClick={record} disabled={progress !== null}>{t('again')}</button>
                        <button className="btn gold" style={{ flex: 1 }} onClick={save} disabled={progress !== null}>{t('save')}</button>
                    </div>
                </>
            )}
            {progress !== null && <div className="bar" aria-label={t('uploading')}><i style={{ width: `${Math.round(progress * 100)}%` }} /></div>}
            {status[item.id] && !rec && <p className={status[item.id] === 'saved' ? 'status ok' : 'status'}>{t(`state.${status[item.id]}`)}</p>}
            {err && <p className="err">{err}</p>}
        </div>
    );

    return (
        <div className="tr" lang={lang}>
            <style>{css}</style>
            <div className="wrap">
                {header}
                <p>{t('lede')}</p>
                {body}
            </div>
        </div>
    );
}
